const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([125.93, -20.59]);
  const region = point.buffer(5000); // 5km buffer for analysis

  // Western Australia is UTC+8
  // 11:00 local = 03:00 UTC, 14:00 local = 06:00 UTC
  const date = '2020-01-14';
  const time1Start = ee.Date(date + 'T03:00:00');
  const time1End = ee.Date(date + 'T03:30:00');
  const time2Start = ee.Date(date + 'T06:00:00');
  const time2End = ee.Date(date + 'T06:30:00');

  // 2. Data Acquisition - Himawari-8 for high temporal resolution
  const col1 = ee.ImageCollection('JAXA/HIMAWARI/AHI_BAND_USAGE_SYNTHESIZED/L2_CLOUD_PROPERTY')
    .filterBounds(point)
    .filterDate(time1Start, time1End);

  const col2 = ee.ImageCollection('JAXA/HIMAWARI/AHI_BAND_USAGE_SYNTHESIZED/L2_CLOUD_PROPERTY')
    .filterBounds(point)
    .filterDate(time2Start, time2End);

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  console.log(`11:00 local images: ${size1}`);
  console.log(`14:00 local images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("Missing data for one or both time periods.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate cloud cover percentage
  const img1 = col1.first();
  const img2 = col2.first();

  // Cloud mask band: 1 = cloudy, 0 = clear
  const cloudMask1 = img1.select('cloud_mask');
  const cloudMask2 = img2.select('cloud_mask');

  // Calculate statistics
  const stats1 = await cloudMask1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 2000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = await cloudMask2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 2000,
    maxPixels: 1e9
  }).getInfo();

  const cloudCover1 = stats1.cloud_mask_mean;
  const count1 = stats1.cloud_mask_count;
  const cloudCover2 = stats2.cloud_mask_mean;
  const count2 = stats2.cloud_mask_count;

  console.log(`11:00 local: Cloud cover = ${(cloudCover1 * 100).toFixed(1)}%, Pixels = ${count1}`);
  console.log(`14:00 local: Cloud cover = ${(cloudCover2 * 100).toFixed(1)}%, Pixels = ${count2}`);

  // 4. Validation
  if (count1 === 0 || count2 === 0) {
    console.log("No valid pixels in analysis region.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (cloudCover1 === null || cloudCover2 === null || 
      cloudCover1 === undefined || cloudCover2 === undefined ||
      isNaN(cloudCover1) || isNaN(cloudCover2)) {
    console.log("Calculation failure - invalid values.");
    console.log("<answer>C3</answer>");
    return;
  }

  // 5. Final Answer
  const increase = cloudCover2 - cloudCover1;
  console.log(`Change: ${(increase * 100).toFixed(1)}% (${increase > 0 ? 'increase' : 'decrease'})`);

  if (cloudCover2 > cloudCover1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
